export function patchRenderer(s){assert.equal(sha(s),BASE_RENDERER_SHA);const n=s.replace(RENDERER_ANCHOR,()=>RENDERER_NEXT).replace(START_OLD,()=>START_NEW);assert.equal(n.replace(RENDERER_NEXT,RENDERER_ANCHOR).replace(START_NEW,START_OLD),s);assert.equal(sha(n),CANDIDATE_RENDERER_SHA);return n}export function patchMain(s){assert.equal(sha(s),MAIN_SHA,'ACTIVE_SOURCE_DRIFT');assert.equal(s.split(ANCHOR).length,2);const n=s.replace(ANCHOR,NEXT)+HELPER+WRAPPER;assert.equal(n.replace(HELPER+WRAPPER,'').replace(NEXT,ANCHOR),s);assert.equal(sha(n),CANDIDATE_SHA);return n}
